    "dataSources": {
        "ds_0d278tIx_ds_wahErERv_ds_2YOW63hy": {
            "name": "setup_mltk_configuration_setup_querylength_detection",
            "options": {
                "query": "| `dns_data` | eval query_length = len(query) | where isnotnull(query_length) AND query_length > 0 | fields _time src query query_length | anomalydetection \"query_length\" \"query\" action=annotate | eval isOutlier = if(probable_cause != \"\", \"1\", \"0\") | where isOutlier=1 | `extract_sub_domain` | eval last_update = now(), anomalous_type = \"Query Length\", _key = domain .\"#\". anomalous_type | table _key, last_update, domain, anomalous_type | `update_anomalous_dns`\n| search dummy=\"dummy\"\n| append \n    [| makeresults | eval result = \"Anomalies Saved\"]\n",
                "queryParameters": {
                    "earliest": "0",
                    "latest": ""
                }
            },
            "type": "ds.search"
        },
        "ds_1IGA3Wda_ds_vJXg1jfX_ds_2YOW63hy": {
            "name": "setup_mltk_configuration_setup_beaconing_detection_model copy 13",
            "options": {
                "query": "| `dns_data` | `extract_sub_domain` | streamstats current=f last(_time) as last_time by src, domain | eval gap = last_time - _time | fit DensityFunction gap by \"src,domain\" dist=norm threshold=0.01 into dns_beacon_gap_model\n| search dummy=\"dummy\"\n| append \n    [| makeresults | eval result = \"Model Trained\"]\n",
                "queryParameters": {
                    "earliest": "$time_beaconing_model_training.earliest$",
                    "latest": "$time_beaconing_model_training.latest$"
                }
            },
            "type": "ds.search"
        },
        "ds_1UDJ5Cdm_ds_wahErERv_ds_2YOW63hy": {
            "name": "setup_mltk_configuration_setup_recordtype_hinfo_detection",
            "options": {
                "query": "| `dns_data` | `extract_sub_domain` | bin _time span=1h | stats count(eval(record_type=\"HINFO\")) as hinfo_queries by _time,src,domain | anomalydetection \"hinfo_queries\" \"domain\" action=annotate | eval isOutlier = if(probable_cause != \"\", \"1\", \"0\") | where isOutlier=1 | eval last_update = now(), anomalous_type = \"HINFO Record Anomalies\", _key = domain .\"#\". anomalous_type | table _key, last_update, domain, anomalous_type | `update_anomalous_dns`\n| search dummy=\"dummy\"\n| append \n    [| makeresults | eval result = \"Anomalies Saved\"]\n",
                "queryParameters": {
                    "earliest": "0",
                    "latest": ""
                }
            },
            "type": "ds.search"
        },
        "ds_2YOW63hy": {
            "name": "setup_mltk_configuration_setup_beaconing_detection_model",
            "options": {
                "query": "| `dns_data` | `extract_sub_domain` \n| fields _time src domain | streamstats current=f last(_time) as last_time by src, domain | eval gap = last_time - _time | fit DensityFunction gap by \"src,domain\" dist=norm threshold=0.01 into dns_beacon_gap_model\n| search dummy=\"dummy\"\n| append \n    [| makeresults | eval result = \"Model Trained\"]\n",
                "queryParameters": {
                    "earliest": "0",
                    "latest": ""
                }
            },
            "type": "ds.search"
        },
        "ds_9ntQovTi_ds_2YOW63hy": {
